Import-Module 'c:/Projects/ProphetManX/prophets-pipelines/conventions/scripts/AgentEvidence.psm1' -PassThru | ForEach-Object {
    $ErrorActionPreference = 'Stop'
    $root = 'c:/Projects/ProphetManX/ProphetsWay.Logger'
    $run = 'c:/Projects/ProphetManX/.agent-runs/20260915-2052-logger-overnight-approval'
    $evidence = Join-Path $run 'evidence'
    $tasksPath = [IO.Path]::GetFullPath((Join-Path $root '.vscode/tasks.json'))
    $protected = Get-Content -LiteralPath (Join-Path $evidence 'on02-protected-specifications-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not (Compare-AgentManifest -Baseline $protected).Matches) { throw 'Protected inputs changed before A1 verification.' }
    $results = @()
    foreach ($leg in @('net48', 'net10')) {
        $author = Get-Content -LiteralPath (Join-Path $evidence ('on02-11-off-' + $leg + '-test.json')) -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $oldInputs = Get-Content -LiteralPath $author.InputManifestPath -Raw | ConvertFrom-Json -Depth 30
        $difference = Compare-AgentManifest -Baseline $oldInputs
        $unexpected = @($difference.Changed | Where-Object { -not [StringComparer]::OrdinalIgnoreCase.Equals($_, $tasksPath) })
        if ($difference.Added.Count -gt 0 -or $difference.Removed.Count -gt 0 -or $unexpected.Count -gt 0) { throw 'A1 author input changed outside authorized task append.' }
        $inputs = New-AgentManifest -Revision ('ON-02 parent A1 ' + $leg + ' current task invocation inputs') -Roots $oldInputs.Selectors.Roots -Patterns $oldInputs.Selectors.Patterns -Paths $oldInputs.Selectors.Paths -ExcludedDirectories $oldInputs.Selectors.ExcludedDirectories
        $inputPath = Save-AgentEvidence -Value $inputs -RunDirectory $run -Name ('on02-parent-A1-' + $leg + '-inputs.json')
        $arguments = @($author.Arguments | ForEach-Object { if ($_ -eq ('trx;LogFileName=on02-11-off-' + $leg + '.trx')) { 'trx;LogFileName=on02-parent-A1-' + $leg + '.trx' } else { $_ } })
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $root -Configuration $author.Configuration -InputManifestPath $inputPath -RunDirectory $run -Name ('on02-parent-A1-' + $leg) -Kind Tests -TrxPath (Join-Path $evidence ('on02-parent-A1-' + $leg + '.trx')) -TimeoutSeconds 600
        $expected = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $author.Results.Tests) { $null = $expected.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $actual = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $validation.Record.Results.Tests) { $null = $actual.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $passed = $validation.Record.Success -and $expected.Count -eq 43 -and $actual.Count -eq 43 -and $expected.SetEquals($actual)
        $results += [pscustomobject][ordered]@{ Leg = $leg; Validation = $validation.Path; AuthorizedTaskInputDifference = $difference; Counts = $validation.Record.Results.Counts; OrdinalCaseMatch = $expected.SetEquals($actual); Passed = $passed }
        if (-not $passed) { throw 'A1 independent target verification failed.' }
    }
    $preserved = Compare-AgentManifest -Baseline $protected
    $summary = [pscustomobject][ordered]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Results = $results; Protected = $preserved; Passed = ($preserved.Matches -and @($results | Where-Object { -not $_.Passed }).Count -eq 0) }
    Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on02-parent-A1-summary.json'
    $summary | ConvertTo-Json -Depth 6
    if (-not $summary.Passed) { throw 'A1 protected inputs changed during independent checks.' }
}

Import-Module 'c:/Projects/ProphetManX/prophets-pipelines/conventions/scripts/AgentEvidence.psm1' -PassThru | ForEach-Object {
    $ErrorActionPreference = 'Stop'
    $root = 'c:/Projects/ProphetManX/ProphetsWay.Logger'
    $run = 'c:/Projects/ProphetManX/.agent-runs/20260915-2052-logger-overnight-approval'
    $evidence = Join-Path $run 'evidence'
    $tasksPath = [IO.Path]::GetFullPath((Join-Path $root '.vscode/tasks.json'))
    $coverage = Get-Content -LiteralPath (Join-Path $evidence 'on02-12-collector-existing-coverage.json') -Raw | ConvertFrom-Json -Depth 40
    $coverageRows = @()
    foreach ($file in $coverage.Files) {
        $hash = (Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash
        if ($hash -cne $file.SHA256) { throw 'Preserved coverage file changed.' }
        $settings = [Xml.XmlReaderSettings]::new()
        $settings.DtdProcessing = [Xml.DtdProcessing]::Prohibit
        $settings.XmlResolver = $null
        $reader = [Xml.XmlReader]::Create($file.Path, $settings)
        $document = [Xml.XmlDocument]::new()
        $document.XmlResolver = $null
        try { $document.Load($reader) } finally { $reader.Dispose() }
        $label = @($document.SelectNodes('/coverage/packages/package/classes/class') | Where-Object { $_.GetAttribute('name') -eq 'ProphetsWay.Utilities.SensitivityLabel' })
        $hits = @($label | ForEach-Object { $_.SelectNodes('./lines/line') } | Where-Object { [long]$_.GetAttribute('hits') -gt 0 }).Count
        if ($hits -eq 0) { throw 'Preserved collector output lacks real label hits.' }
        $coverageRows += [pscustomobject]@{ Path = $file.Path; SHA256 = $hash; LabelHitLines = $hits }
    }
    if (@($coverageRows.SHA256 | Sort-Object -Unique).Count -ne 1) { throw 'Coverage copies disagree.' }
    Save-AgentEvidence -Value ([pscustomobject]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Copies = $coverageRows; ByteIdentical = $true; Scope = 'Historical reverted net48 trial only; no current collector or net10 coverage claim' }) -RunDirectory $run -Name 'on02-parent-coverage-copy-diagnosis.json'
    $protected = Get-Content -LiteralPath (Join-Path $evidence 'on02-protected-specifications-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not (Compare-AgentManifest -Baseline $protected).Matches) { throw 'Protected inputs changed.' }
    $results = @()
    foreach ($leg in @('net48', 'net10')) {
        $author = Get-Content -LiteralPath (Join-Path $evidence ('on02-12-reverted-collector-' + $leg + '-test.json')) -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $oldInputs = Get-Content -LiteralPath $author.InputManifestPath -Raw | ConvertFrom-Json -Depth 30
        $difference = Compare-AgentManifest -Baseline $oldInputs
        if ($difference.Added.Count -gt 0 -or $difference.Removed.Count -gt 0 -or @($difference.Changed | Where-Object { -not [StringComparer]::OrdinalIgnoreCase.Equals($_, $tasksPath) }).Count -gt 0) { throw 'Unexpected current input drift.' }
        $inputs = New-AgentManifest -Revision ('ON-02 parent auxiliary ' + $leg) -Roots $oldInputs.Selectors.Roots -Patterns $oldInputs.Selectors.Patterns -Paths $oldInputs.Selectors.Paths -ExcludedDirectories $oldInputs.Selectors.ExcludedDirectories
        $inputPath = Save-AgentEvidence -Value $inputs -RunDirectory $run -Name ('on02-parent-aux-' + $leg + '-inputs.json')
        $arguments = @($author.Arguments | ForEach-Object { if ($_ -eq ('trx;LogFileName=on02-12-reverted-collector-' + $leg + '-test.trx')) { 'trx;LogFileName=on02-parent-aux-' + $leg + '.trx' } elseif ($_ -eq $author.Arguments[-1]) { $evidence } else { $_ } })
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $root -Configuration $author.Configuration -InputManifestPath $inputPath -RunDirectory $run -Name ('on02-parent-aux-' + $leg) -Kind Tests -TrxPath (Join-Path $evidence ('on02-parent-aux-' + $leg + '.trx')) -TimeoutSeconds 600
        $expected = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $author.Results.Tests) { $null = $expected.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $actual = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $validation.Record.Results.Tests) { $null = $actual.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $passed = $validation.Record.Success -and $actual.Count -eq 43 -and $expected.SetEquals($actual)
        $results += [pscustomobject]@{ Leg = $leg; Validation = $validation.Path; Counts = $validation.Record.Results.Counts; CaseMatch = $expected.SetEquals($actual); Passed = $passed }
        if (-not $passed) { throw 'Retained auxiliary state failed independent verification.' }
    }
    $preserved = Compare-AgentManifest -Baseline $protected
    $summary = [pscustomobject]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Results = $results; Protected = $preserved; Passed = $preserved.Matches }
    Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on02-parent-aux-summary.json'
    $summary | ConvertTo-Json -Depth 6
    if (-not $summary.Passed) { throw 'Protected inputs changed during checks.' }
}

Import-Module 'c:/Projects/ProphetManX/prophets-pipelines/conventions/scripts/AgentEvidence.psm1' -PassThru | ForEach-Object {
    $ErrorActionPreference = 'Stop'
    $root = 'c:/Projects/ProphetManX/ProphetsWay.Logger'
    $run = 'c:/Projects/ProphetManX/.agent-runs/20260915-2052-logger-overnight-approval'
    $evidence = Join-Path $run 'evidence'
    $tasksPath = [IO.Path]::GetFullPath((Join-Path $root '.vscode/tasks.json'))
    $protected = Get-Content -LiteralPath (Join-Path $evidence 'on02-protected-specifications-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not (Compare-AgentManifest -Baseline $protected).Matches) { throw 'Protected inputs changed before independent coverage.' }
    $results = @()
    foreach ($leg in @('net48', 'net10')) {
        $author = Get-Content -LiteralPath (Join-Path $evidence ('on02-13-collector-' + $leg + '-test.json')) -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $oldInputs = Get-Content -LiteralPath $author.InputManifestPath -Raw | ConvertFrom-Json -Depth 30
        $difference = Compare-AgentManifest -Baseline $oldInputs
        if ($difference.Added.Count -gt 0 -or $difference.Removed.Count -gt 0 -or @($difference.Changed | Where-Object { -not [StringComparer]::OrdinalIgnoreCase.Equals($_, $tasksPath) }).Count -gt 0) { throw 'Unexpected current coverage input drift.' }
        $inputs = New-AgentManifest -Revision ('ON-02 parent collector ' + $leg) -Roots $oldInputs.Selectors.Roots -Patterns $oldInputs.Selectors.Patterns -Paths $oldInputs.Selectors.Paths -ExcludedDirectories $oldInputs.Selectors.ExcludedDirectories
        $inputPath = Save-AgentEvidence -Value $inputs -RunDirectory $run -Name ('on02-parent-collector-' + $leg + '-inputs.json')
        $arguments = @($author.Arguments)
        for ($index = 0; $index -lt $arguments.Count; $index++) {
            if ($arguments[$index] -eq '--logger') { $arguments[$index + 1] = 'trx;LogFileName=on02-parent-collector-' + $leg + '.trx' }
            if ($arguments[$index] -eq '--results-directory') { $arguments[$index + 1] = $evidence }
        }
        $trxPath = Join-Path $evidence ('on02-parent-collector-' + $leg + '.trx')
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $root -Configuration $author.Configuration -InputManifestPath $inputPath -RunDirectory $run -Name ('on02-parent-collector-' + $leg) -Kind Tests -TrxPath $trxPath -TimeoutSeconds 600
        if (-not $validation.Record.Success) { throw 'Independent coverage execution failed.' }
        $expected = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $author.Results.Tests) { $null = $expected.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $actual = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $validation.Record.Results.Tests) { $null = $actual.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        if ($actual.Count -ne 43 -or -not $expected.SetEquals($actual)) { throw 'Coverage test membership changed.' }
        $settings = [Xml.XmlReaderSettings]::new()
        $settings.DtdProcessing = [Xml.DtdProcessing]::Prohibit
        $settings.XmlResolver = $null
        $trxReader = [Xml.XmlReader]::Create($trxPath, $settings)
        $trx = [Xml.XmlDocument]::new()
        $trx.XmlResolver = $null
        try { $trx.Load($trxReader) } finally { $trxReader.Dispose() }
        $deployment = @($trx.GetElementsByTagName('Deployment'))
        if ($deployment.Count -ne 1) { throw 'Missing TRX deployment metadata.' }
        $collectors = @($trx.GetElementsByTagName('Collector') | Where-Object { $_.GetAttribute('uri') -eq 'datacollector://microsoft/CoverletCodeCoverage/1.0' })
        if ($collectors.Count -eq 0) { throw 'Missing Coverlet attachment metadata.' }
        $attachments = @()
        foreach ($collector in $collectors) {
            foreach ($link in $collector.GetElementsByTagName('A')) {
                $path = Join-Path (Join-Path (Join-Path $evidence $deployment[0].GetAttribute('runDeploymentRoot')) 'In') $link.GetAttribute('href')
                $coverageReader = [Xml.XmlReader]::Create($path, $settings)
                $coverage = [Xml.XmlDocument]::new()
                $coverage.XmlResolver = $null
                try { $coverage.Load($coverageReader) } finally { $coverageReader.Dispose() }
                $module = @($coverage.GetElementsByTagName('package') | Where-Object { $_.GetAttribute('name') -eq 'ProphetsWay.Logger' })
                $label = @($module | ForEach-Object { $_.GetElementsByTagName('class') } | Where-Object { $_.GetAttribute('name') -eq 'ProphetsWay.Utilities.SensitivityLabel' })
                $moduleHits = @($module | ForEach-Object { $_.SelectNodes('./classes/class/lines/line') } | Where-Object { [long]$_.GetAttribute('hits') -gt 0 }).Count
                $labelHits = @($label | ForEach-Object { $_.SelectNodes('./lines/line') } | Where-Object { [long]$_.GetAttribute('hits') -gt 0 }).Count
                if ($moduleHits -eq 0 -or $labelHits -eq 0) { throw 'No meaningful module/label coverage.' }
                $attachments += [pscustomobject]@{ Path = $path; SHA256 = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash; ModuleHitLines = $moduleHits; LabelHitLines = $labelHits }
            }
        }
        if ($attachments.Count -eq 0) { throw 'No coverage attachments were checked.' }
        $results += [pscustomobject]@{ Leg = $leg; Validation = $validation.Path; Counts = $validation.Record.Results.Counts; CaseMatch = $true; Coverage = $attachments; Passed = $true }
    }
    $preserved = Compare-AgentManifest -Baseline $protected
    $summary = [pscustomobject]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Results = $results; Protected = $preserved; Passed = $preserved.Matches }
    Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on02-parent-collector-summary.json'
    $summary | ConvertTo-Json -Depth 7
    if (-not $summary.Passed) { throw 'Protected inputs changed during collector verification.' }
}

Import-Module 'c:/Projects/ProphetManX/prophets-pipelines/conventions/scripts/AgentEvidence.psm1' -PassThru | ForEach-Object {
    $ErrorActionPreference = 'Stop'
    $root = 'c:/Projects/ProphetManX/ProphetsWay.Logger'
    $run = 'c:/Projects/ProphetManX/.agent-runs/20260915-2052-logger-overnight-approval'
    $evidence = Join-Path $run 'evidence'
    $tasksPath = [IO.Path]::GetFullPath((Join-Path $root '.vscode/tasks.json'))
    $protected = Get-Content -LiteralPath (Join-Path $evidence 'on02-protected-specifications-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not (Compare-AgentManifest -Baseline $protected).Matches) { throw 'Protected inputs changed.' }
    function Get-CurrentInputs($record, $name) {
        $oldInputs = Get-Content -LiteralPath $record.InputManifestPath -Raw | ConvertFrom-Json -Depth 30
        $difference = Compare-AgentManifest -Baseline $oldInputs
        if ($difference.Added.Count -gt 0 -or $difference.Removed.Count -gt 0 -or @($difference.Changed | Where-Object { -not [StringComparer]::OrdinalIgnoreCase.Equals($_, $tasksPath) }).Count -gt 0) { throw 'Unexpected final-matrix input drift.' }
        $inputs = New-AgentManifest -Revision $name -Roots $oldInputs.Selectors.Roots -Patterns $oldInputs.Selectors.Patterns -Paths $oldInputs.Selectors.Paths -ExcludedDirectories $oldInputs.Selectors.ExcludedDirectories
        Save-AgentEvidence -Value $inputs -RunDirectory $run -Name ($name + '-inputs.json')
    }
    $builds = @()
    foreach ($kind in @('library', 'example')) {
        $author = Get-Content -LiteralPath (Join-Path $evidence ('on02-14-example-net10-' + $kind + '-build.json')) -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $name = 'on02-parent-final-' + $kind + '-build'
        $inputPath = Get-CurrentInputs $author $name
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $author.Arguments -WorkingDirectory $root -Configuration $author.Configuration -InputManifestPath $inputPath -RunDirectory $run -Name $name -TimeoutSeconds 600
        if (-not $validation.Record.Success) { throw 'Final matrix build failed.' }
        $builds += $validation.Path
    }
    $settings = [Xml.XmlReaderSettings]::new()
    $settings.DtdProcessing = [Xml.DtdProcessing]::Prohibit
    $settings.XmlResolver = $null
    $results = @()
    foreach ($pair in @(@{ Leg = 'net48'; Framework = 'net48'; Asset = 'netstandard2.0'; TargetName = '.NETStandard,Version=v2.0' }, @{ Leg = 'net10'; Framework = 'net10.0'; Asset = 'net10.0'; TargetName = '.NETCoreApp,Version=v10.0' })) {
        $leg = $pair.Leg
        $author = Get-Content -LiteralPath (Join-Path $evidence ('on02-14-example-net10-' + $leg + '-test.json')) -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $name = 'on02-parent-final-matrix-' + $leg
        $inputPath = Get-CurrentInputs $author $name
        $built = Join-Path $root ('ProphetsWay.Logger/bin/Debug/' + $pair.Asset + '/ProphetsWay.Logger.dll')
        $copied = Join-Path $root ('ProphetsWay.Logger.Test/bin/Debug/' + $pair.Framework + '/ProphetsWay.Logger.dll')
        $builtHash = (Get-FileHash -LiteralPath $built -Algorithm SHA256).Hash
        $copiedHash = (Get-FileHash -LiteralPath $copied -Algorithm SHA256).Hash
        if ($builtHash -cne $copiedHash) { throw 'Test copy is not the approved library asset.' }
        $assembly = [Reflection.Assembly]::LoadFile([IO.Path]::GetFullPath($built))
        $targetAttribute = @($assembly.GetCustomAttributesData() | Where-Object { $_.AttributeType.FullName -eq 'System.Runtime.Versioning.TargetFrameworkAttribute' })
        if ($targetAttribute.Count -ne 1 -or $targetAttribute[0].ConstructorArguments[0].Value -cne $pair.TargetName) { throw 'Built library target metadata is wrong.' }
        $arguments = @($author.Arguments)
        for ($index = 0; $index -lt $arguments.Count; $index++) {
            if ($arguments[$index] -eq '--logger') { $arguments[$index + 1] = 'trx;LogFileName=' + $name + '.trx' }
            if ($arguments[$index] -eq '--results-directory') { $arguments[$index + 1] = $evidence }
        }
        $trxPath = Join-Path $evidence ($name + '.trx')
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $root -Configuration $author.Configuration -InputManifestPath $inputPath -RunDirectory $run -Name $name -Kind Tests -TrxPath $trxPath -TimeoutSeconds 600
        if (-not $validation.Record.Success) { throw 'Final matrix test/coverage execution failed.' }
        $expected = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $author.Results.Tests) { $null = $expected.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        $actual = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
        foreach ($case in $validation.Record.Results.Tests) { $null = $actual.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
        if ($actual.Count -ne 43 -or -not $expected.SetEquals($actual)) { throw 'Final matrix case membership changed.' }
        $reader = [Xml.XmlReader]::Create($trxPath, $settings)
        $trx = [Xml.XmlDocument]::new()
        $trx.XmlResolver = $null
        try { $trx.Load($reader) } finally { $reader.Dispose() }
