    $examples = Get-Content -LiteralPath (Join-Path $evidence 'on04-readme-compilation-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not $examples.Passed -or $examples.Compiled -ne 10 -or $examples.Executed -or (Get-FileHash -LiteralPath $examples.README -Algorithm SHA256).Hash -cne $examples.ReadmeSHA256) { throw 'README compile evidence stale or incomplete.' }
    foreach ($example in $examples.Examples) { if (-not $example.EmittedInMemory -or $example.Executed -or (Get-FileHash -LiteralPath $example.Library -Algorithm SHA256).Hash -cne $example.LibrarySHA256) { throw 'README compile library identity changed.' } }
    $sourceReview = Get-Content -LiteralPath (Join-Path $evidence 'on04-parent-green-inputs-r1.json') -Raw | ConvertFrom-Json -Depth 30
    $reviewedComparison = Compare-AgentManifest $sourceReview
    $taskPath = Join-Path $repository '.vscode/tasks.json'
    if ($reviewedComparison.Added.Count -ne 0 -or $reviewedComparison.Removed.Count -ne 0 -or @($reviewedComparison.Changed | Where-Object { $_ -cne $taskPath }).Count -ne 0) { throw 'Code/security-reviewed implementation changed.' }
    $finalCandidate = Compare-AgentManifest $candidate
    $finalInputs = Compare-AgentManifest $inputs
    $specComparison = Compare-AgentManifest $frozen
    $protectedComparison = Compare-AgentManifest $protected
    if (-not $finalCandidate.Matches -or -not $finalInputs.Matches -or -not $specComparison.Matches -or -not $protectedComparison.Matches) { throw 'Final preservation gate failed.' }
    $summary = [pscustomobject]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Head = $expectedHead; Branch = $branch; ProductPaths = $allowed; CandidateManifest = $candidatePath; GitCandidate = (Join-Path $evidence 'on04-final-git-candidate-r1.json'); InputManifest = $inputPath; Builds = $builds; Runs = $runs; ExamplesCompiled = $examples.Compiled; ExamplesExecuted = $false; ReviewedSourceComparison = $reviewedComparison; CandidateComparison = $finalCandidate; FrozenSpecifications = $specComparison; ProtectedInputs = $protectedComparison; OriginalTasksPreserved = $originalTasks.tasks.Count; NewTasks = @($tasks.tasks | Select-Object -Skip $originalTasks.tasks.Count | ForEach-Object label); CommitAttempted = $false; Passed = $true }
    $null = Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on04-parent-final-summary-r1.json'
    [pscustomobject]@{ ProductPaths = $allowed.Count; BuildsPassed = $builds.Count; TestRuns = @($runs | Select-Object Framework, Counts, AuditedIdentitiesUnchanged, Asset); ExamplesCompiled = $examples.Compiled; ExamplesExecuted = $false; FrozenInputsMatch = $specComparison.Matches; ProtectedInputsMatch = $protectedComparison.Matches; CandidateUnchanged = $finalCandidate.Matches; Passed = $true } | ConvertTo-Json -Depth 7
}
